export const samlCallback = async (id: number,
    samlAssertion: SamlAssertion, options?: Parameters<typeof customFetch>[1]): Promise<unknown> => {
    const formUrlEncoded = new URLSearchParams();
formUrlEncoded.append(`SAMLResponse`, samlAssertion.SAMLResponse);
if(samlAssertion.RelayState !== undefined) {
 formUrlEncoded.append(`RelayState`, samlAssertion.RelayState);
 }

    const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(h as Iterable<Iterable<string>>, (entry) => Array.from(entry) as [string, string]),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
return customFetch<unknown>(getSamlCallbackUrl(id),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded', ...getHeaders(options?.headers) },
    body: formUrlEncoded
  }
);}





